def fix_spaces(text):
    if not text:
        return ""

    # Replace multiple spaces with a single placeholder
    parts = text.split(' ')
    result = []

    for part in parts:
        if part:
            result.append(part)
        else:
            if result and result[-1] != '-':
                result.append('-')

    # Join parts with underscores
    final_result = '_'.join(result)

    # Handle leading/trailing underscores if needed
    if text.startswith(' '):
        final_result = '_' + final_result
    if text.endswith(' '):
        final_result += '_'

    return final_result

